<?php
if(!defined('ABSPATH'))exit;
add_action('plugins_loaded',function(){if(!class_exists('WC_Payment_Gateway'))return;class SF_Demo_Gateway extends WC_Payment_Gateway{public function __construct(){$this->id='sf_demo';$this->method_title='ServiceFlow Demo — no real payment';$this->has_fields=true;$this->init_form_fields();$this->init_settings();$this->title='Демонстрація — без списання коштів';$this->description='Локальна симуляція замовлення. Це не sandbox платіжного провайдера.';$this->enabled=$this->get_option('enabled','no');add_action('woocommerce_update_options_payment_gateways_'.$this->id,[$this,'process_admin_options']);}public function init_form_fields(){$this->form_fields=['enabled'=>['title'=>'Демо-шлюз','type'=>'checkbox','label'=>'Увімкнути лише на тестовому сайті','default'=>'no']];}public function payment_fields(){echo '<p>'.esc_html($this->description).'</p><label><input type="checkbox" name="sf_payment_failure" value="1"> Симулювати відмову платежу</label>';}public function process_payment($order_id){$order=wc_get_order($order_id);if(!empty($_POST['sf_payment_failure'])){wc_add_notice('Симуляція відмови. Реальних коштів не списано.','error');return ['result'=>'failure'];}$order->update_meta_data('_sf_demo_order','yes');$order->save();$order->update_status('on-hold','ServiceFlow: simulated checkout. No provider payment.');WC()->cart->empty_cart();return ['result'=>'success','redirect'=>$this->get_return_url($order)];}}});
add_filter('woocommerce_payment_gateways',function($g){$g[]='SF_Demo_Gateway';return $g;});
add_action('rest_api_init',function(){register_rest_route('serviceflow/v1','/cart',['methods'=>'POST','permission_callback'=>'sf_public_permission','callback'=>function($r){if(!class_exists('WooCommerce'))return sf_error('WooCommerce is unavailable.',503);$d=$r->get_json_params();$c=sf_catalog();$id=sanitize_key($d['id']??'');$p=current(array_filter($c['packages'],fn($x)=>$x['id']===$id));$car=sanitize_key($d['carType']??'car');$type=current(array_filter($c['carTypes'],fn($x)=>$x['id']===$car));$opts=$d['extras']??[];if(!$p||!$type||!is_array($opts)||count(array_diff($opts,array_column($c['extras'],'id'))))return sf_error('Invalid package.');$sku=wc_get_product_id_by_sku('sf-'.$id);if(!$sku)return sf_error('Пакети ще не створені. Запустіть налаштування ServiceFlow.',503);if(!WC()->session)WC()->initialize_session();if(!WC()->cart)wc_load_cart();$meta=['sf_package'=>$id,'sf_car'=>$car,'sf_extras'=>array_values(array_unique($opts))];$key=WC()->cart->add_to_cart($sku,1,0,[],$meta);if(!$key)return sf_error('Cart error.',503);return ['ok'=>true,'redirect'=>wc_get_cart_url()];}]);});
add_action('woocommerce_before_calculate_totals',function($cart){if(is_admin()&&!wp_doing_ajax())return;$c=sf_catalog();foreach($cart->get_cart() as $item){if(empty($item['sf_package']))continue;$p=current(array_filter($c['packages'],fn($x)=>$x['id']===$item['sf_package']));$type=current(array_filter($c['carTypes'],fn($x)=>$x['id']===($item['sf_car']??'car')));if(!$p||!$type)continue;$price=round($p['price']*$type['factor']);foreach($c['extras'] as $extra)if(in_array($extra['id'],$item['sf_extras']??[],true))$price+=$extra['price'];$item['data']->set_price($price);}},20);
add_filter('woocommerce_get_item_data',function($data,$item){if(!empty($item['sf_car']))$data[]=['key'=>'Тип авто','value'=>esc_html($item['sf_car'])];if(!empty($item['sf_extras']))$data[]=['key'=>'Опції','value'=>esc_html(implode(', ',$item['sf_extras']))];return $data;},10,2);
add_action('woocommerce_checkout_create_order_line_item',function($line,$key,$values){foreach(['sf_package','sf_car','sf_extras'] as $name)if(isset($values[$name]))$line->add_meta_data($name,is_array($values[$name])?implode(', ',$values[$name]):$values[$name]);},10,3);
add_action('woocommerce_review_order_before_submit',function(){woocommerce_form_field('sf_consent',['type'=>'checkbox','required'=>true,'label'=>'Розумію, що це демонстраційне замовлення без реальної оплати.']);});
add_action('woocommerce_checkout_process',function(){if(empty($_POST['sf_consent']))wc_add_notice('Підтвердьте умови демонстраційного замовлення.','error');});
add_action('woocommerce_checkout_order_processed',function($order_id,$posted,$order){$order->update_meta_data('_sf_source','order');$order->save();},10,3);
add_action('woocommerce_account_dashboard',function(){if(!is_user_logged_in())return;global $wpdb;$t=sf_tables();$uid=get_current_user_id();$rows=$wpdb->get_results($wpdb->prepare("SELECT lead_id,service,status,created_at FROM {$t['leads']} WHERE user_id=%d ORDER BY id DESC LIMIT 100",$uid),ARRAY_A);echo '<h2>Мої заявки ServiceFlow</h2><table><thead><tr><th>Дата</th><th>Послуга</th><th>Статус</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.esc_html($r['created_at']).'</td><td>'.esc_html($r['service']).'</td><td>'.esc_html($r['status']).'</td></tr>';echo '</tbody></table><h2>Мої автомобілі</h2>';foreach(get_user_meta($uid,'sf_cars',true)?:[] as $car)echo '<p>'.esc_html($car['model']).' · '.(int)$car['year'].'</p>';echo '<form action="'.esc_url(admin_url('admin-post.php')).'" method="post"><input type="hidden" name="action" value="sf_save_car">';wp_nonce_field('sf_save_car');echo '<p><label>Марка та модель<input name="model" maxlength="100" required></label></p><p><label>Рік<input type="number" name="year" min="1980" max="'.((int)date('Y')+1).'" required></label></p><button type="submit">Додати автомобіль</button></form>';});
add_action('admin_post_sf_save_car',function(){if(!is_user_logged_in())wp_die('Forbidden',403);check_admin_referer('sf_save_car');$model=sanitize_text_field(substr($_POST['model']??'',0,100));$year=(int)($_POST['year']??0);if(!$model||$year<1980||$year>(int)date('Y')+1)wp_die('Invalid vehicle');$id=get_current_user_id();$cars=get_user_meta($id,'sf_cars',true)?:[];if(count($cars)>=10)wp_die('Maximum 10 cars');$cars[]=['model'=>$model,'year'=>$year];update_user_meta($id,'sf_cars',$cars);wp_safe_redirect(wc_get_page_permalink('myaccount'));exit;});
